
DROP TABLE IF EXISTS submarine_cables;
CREATE TABLE submarine_cables (
  id SERIAL PRIMARY KEY,
  name TEXT,
  operator TEXT,
  category TEXT NOT NULL,
  status TEXT NOT NULL,
  wikidata TEXT,
  geom geometry(LineString, 4326) NOT NULL
);

CREATE INDEX submarine_cables_geom_idx ON submarine_cables USING GIST (geom);
SELECT category, status, count(*) FROM submarine_cables GROUP BY category, status ORDER BY count(*) DESC;